function load(){
 try{const saved=localStorage.getItem(STORAGE);if(saved){const x=JSON.parse(saved);if(x&&Array.isArray(x.consoles)&&Array.isArray(x.games)&&Array.isArray(x.cheats)){x.settings=x.settings||{};return x;}}}catch(err){console.warn("Dados locais indisponíveis:",err);}
 return startData();
}
let data=load(),filterGenre="Todos",searchTerm="",sortValue="az",bookPage=0,menuOpen=false,toastTimeout=0;
