function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(data));return true;}catch(err){console.error(err);alert("Sem espaço para salvar. Exporte um backup em Gerenciar e tente uma capa de imagem menor.");return false;}}
if(!localStorage.getItem(STORAGE))persist();
function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function safeImage(v){v=String(v||"");return /^(https?:\/\/|data:image\/(?:jpeg|png|webp);base64,)/i.test(v)?v:"";}
function safeRomURL(v){
 const value=String(v||"").trim();
 if(!value)return "";
 try{
  const url=new URL(value);
  if(!["https:","http:"].includes(url.protocol))return "";
  if(!url.hostname)return "";
  return url.href;
 }catch(_){return "";}
}
function attr(v){return esc(v);}
function uid(prefix){return prefix+"-"+(typeof crypto!=="undefined"&&crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2));}
function gConsole(id){return data.consoles.find(c=>c.id===id);}
function gGame(id){return data.games.find(g=>g.id===id);}
function cheatsFor(id,type){return data.cheats.filter(x=>x.gameId===id&&(!type||x.type===type));}
function gamesFor(id){return data.games.filter(g=>g.consoleId===id);}
function currentColor(c){return /^#[0-9a-f]{6}$/i.test(c?.color||"")?c.color:"#a55cff";}
function colorFor(g){const a={"Ação":["#7734a3","#101a3c"],"Aventura":["#346c9d","#1b2659"],"Corrida":["#f05d77","#182967"],"Luta":["#c63a4f","#22102c"],"Esporte":["#2c9a7b","#14446e"],"Plataforma":["#b252d6","#27368c"],"RPG":["#3f66be","#2a1f59"],"Terror":["#4b3f67","#10101e"],"Estratégia":["#6a9d6d","#193f49"],"Outros":["#7453ae","#19265b"]};return a[g?.genre]||a.Outros;}
function miniCover(g){const [a,b]=colorFor(g);if(!g)return `<div class="empty-mini">+</div>`;return `<div class="mini-cover" style="--cv1:${a};--cv2:${b}" title="${attr(g.title)}"><span class="mini-glyph">${esc(g.emoji||"🎮")}</span></div>`;}
function cover(g){if(!g)return "";const [a,b]=colorFor(g),c=gConsole(g.consoleId),img=safeImage(g.cover);return `<div class="cover-art" style="--cv1:${a};--cv2:${b}">${img?`<img class="cover-upload" src="${attr(img)}" alt="Capa de ${attr(g.title)}" loading="lazy">`:`<span class="cover-console">${esc(c?.name||"JOGO")}</span><div><span class="cover-glyph">${esc(g.emoji||"🎮")}</span><span class="cover-label">${esc(g.title)}</span></div><span class="cover-shine"></span>`}</div>`;}
