 dreamcast:`${box("M60 71L201 71L230 96L226 130L70 130L49 106Z","#e1e3e4","#fff")}${box("M54 103L227 103L226 126L70 126Z","#bfc6cc","#e9edf1")}<ellipse cx="145" cy="92" rx="49" ry="19" fill="#f6f5f5" stroke="#abb7c2" stroke-width="2"/><path d="M147 83q23 1 9 16q-19 12-27-4q-1-9 14-9" fill="none" stroke="#ed814a" stroke-width="5" stroke-linecap="round"/>${controller(127,true)}`,
 ps1:`${box("M59 81L217 81L232 112L229 128L70 130L52 113Z","#c5c7d1","#fafbff")}${box("M55 113L230 113L227 129L70 129Z","#aeb3c0","#d9deea")}<ellipse cx="145" cy="93" rx="55" ry="19" fill="#c9cad4" stroke="#9499ac" stroke-width="3"/><ellipse cx="145" cy="93" rx="26" ry="9" fill="#9b9eae" stroke="#e7e8f2" stroke-width="2"/>${controller(130,true)}`,
